ndAmulet","data":{"name":"Woodland amulet","buy":75,"sell":20,"field":"jewelryOwned","key":"woodlandAmulet","slot":"amulet","skill":"woodXP","bonus":1,"icon":"📿","description":"+1 Woodcutting level and +5% Woodcutting XP while worn."}},{"id":"item:jewelry:prospectorsRing","data":{"name":"Prospector’s ring","buy":75,"sell":20,"field":"jewelryOwned","key":"prospectorsRing","slot":"trinket","skill":"miningXP","bonus":1,"icon":"💍","description":"+1 Mining level and +5% Mining XP while worn."}},{"id":"weapon:battleaxe","data":{"name":"Iron battleaxe","kind":"weapon","damage":14,"attack":16,"speed":2.8,"reach":2.2,"desc":"A one-handed double-headed iron battleaxe. Attack +16 · Damage +14 · Attack turn 2.8s."}},{"id":"weapon:dagger","data":{"name":"Iron dagger","kind":"weapon","damage":5,"attack":8,"speed":1.4,"reach":1.7,"desc":"A light blade for quick thrusts. Attack +8 · Damage +5 · Attack turn 1.4s."}},{"id":"weapon:scimitar","data":{"name":"Iron scimitar","kind":"weapon","damage":7,"attack":12,"speed":1.7,"reach":2.4,"desc":"A swift curved iron blade. Attack +12 · Damage +7 · Attack turn 1.7s."}},{"id":"weapon:longsword","data":{"name":"Iron longsword","kind":"weapon","damage":10,"attack":14,"speed":2.3,"reach":2.5,"desc":"A balanced straight iron sword. Attack +14 · Damage +10 · Attack turn 2.3s."}},{"id":"weapon:twohand","data":{"name":"Iron 2h sword","kind":"weapon","damage":16,"attack":20,"speed":3.2,"reach":2.8,"desc":"A heavy two-handed iron sword. Attack +20 · Damage +16 · Attack turn 3.2s."}},{"id":"weapon:shortsword","data":{"name":"Iron shortsword","kind":"weapon","damage":6,"attack":10,"speed":1.6,"reach":2.1,"desc":"A fast close-range iron sword. Attack +10 · Damage +6 · Attack turn 1.6s."}},{"id":"weapon:pickaxe","data":{"name":"Iron pickaxe","kind":"tool","damage":4,"attack":3,"speed":2.5,"reach":2.1,"desc":"An iron pick for mining ore. Attack +3 · Damage +4 · Attack turn 2.5s."}},{"id":"weapon:axe","data":{"name":"Iron axe","kind":"tool","damage":5,"attack":4,"speed":2.4,"reach":2.1,"desc":"An iron axe for cutting trees. Attack +4 · Damage +5 · Attack turn 2.4s."}},{"id":"armor:helm","data":{"name":"Iron full helm","slot":"Head","defence":4,"reduction":1,"desc":"Iron head protection."}},{"id":"armor:chest","data":{"name":"Iron platebody","slot":"Body","defence":10,"reduction":3,"desc":"Plate armor that absorbs melee damage."}},{"id":"armor:legs","data":{"name":"Iron platelegs","slot":"Legs","defence":7,"reduction":2,"desc":"Articulated iron leg protection."}},{"id":"armor:boots","data":{"name":"Iron boots","slot":"Feet","defence":3,"reduction":1,"desc":"Iron-plated boots."}},{"id":"armor:cape","data":{"name":"Crimson Adventurer Cape","slot":"Back","defence":1,"reduction":0,"desc":"A crimson cape with gold clasps."}},{"id":"shield:square","data":{"name":"Iron square shield","kind":"shield","defence":5,"desc":"A compact rectangular iron shield."}},{"id":"shield:kite","data":{"name":"Iron kiteshield","kind":"shield","defence":9,"desc":"A broad iron shield tapering to a pointed base."}}]'::jsonb)x;
insert into eldervale_private.realm_actors(id,data,x,z,hp) select x->>'id',x->'data',(x->'data'->>'x')::float8,(x->'data'->>'z')::float8,(x->'data'->>'hp')::integer from jsonb_array_elements('[{"id":"base:npc:Edda the Guide","data":{"name":"Edda the Guide","role":"guide","x":3,"z":8,"color":4943245,"station":"guide","behavior":"stationary","lines":["Welcome to Oakcross, the main town of the Heartlands! The stone bank is northwest, the town hall is north, and the inn is southeast.","Visit the market in the square, the forge to the east, or the chapel in the southwest. The northern armory has equipment for new adventurers."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Sir Rowan","data":{"name":"Sir Rowan","role":"guard","x":24,"z":-3,"color":10132902,"station":"guard","behavior":"patrol","patrol":[[24,-3],[28,3],[24,8],[20,4]],"lines":["I patrol the eastern gate and keep the roads safe.","Keep your blade ready beyond the village."],"attackType":"slash","level":20,"hp":110,"damage":12,"attackSpeed":2.4,"kind":"npc","template":"guard","roam":3,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Mira the Herbalist","data":{"name":"Mira the Herbalist","role":"herbalist","x":-12,"z":7.5,"color":5540966,"station":"herbs","behavior":"stationary","lines":["Welcome to my herb stall. Fresh greens and remedies from the forest.","The forests are alive with useful plants."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"activity":"garden","kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Bram the Woodsman","data":{"name":"Bram the Woodsman","role":"woodsman","x":-56,"z":43,"color":8740668,"station":"woodland","behavior":"patrol","patrol":[[-56,43],[-50,40],[-48,45],[-55,47]],"lines":["I collect timber beside Northwatch, not in the middle of town.","The tall pines make fine beams."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"kind":"npc","template":"villager","roam":3,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Lysa the Scout","data":{"name":"Lysa the Scout","role":"scout","x":74,"z":-51,"color":7627403,"station":"scout","behavior":"patrol","patrol":[[74,-51],[80,-48],[83,-54],[76,-55]],"lines":["I keep watch over Eastmarch and its roads.","The eastern roads wind toward Suncrest."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"kind":"npc","template":"villager","roam":3,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Torren the Smith","data":{"name":"Torren the Smith","role":"smith","x":28,"z":-10.8,"color":8416869,"station":"forge","behavior":"stationary","lines":["Welcome to the Ember Forge. These stone walls keep the heat in while I work.","I keep blades and tools ready for travelers. Bring me ore when smithing is available."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"activity":"smith","kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Fen the Ranger","data":{"name":"Fen the Ranger","role":"ranger","x":-208,"z":146,"color":4026709,"station":"ranger","behavior":"patrol","patrol":[[-208,146],[-201,141],[-205,136],[-213,141]],"lines":["I patrol Westmere and watch the forest trails.","Keep your eyes open for landmarks."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"kind":"npc","template":"villager","roam":3,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Nara the Wanderer","data":{"name":"Nara the Wanderer","role":"wanderer","x":258,"z":-181,"color":9530733,"station":"traveler","behavior":"patrol","patrol":[[258,-181],[265,-178],[268,-183],[260,-188]],"lines":["I am resting near Suncrest before my next journey.","The western ruins are older than the kingdoms themselves."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"kind":"npc","template":"villager","roam":3,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Garrick the Banker","data":{"name":"Garrick the Banker","role":"banker","x":-21.5,"z":-21.7,"color":5989766,"station":"bank","behavior":"stationary","lines":["Welcome to Oakcross Bank. Your valuables deserve a safe place.","You will find the tellers in this hall and the iron vault at the back. Personal storage is not available yet."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"activity":"read","kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Pella the Merchant","data":{"name":"Pella the Merchant","role":"merchant","x":12,"z":6.5,"color":10975307,"station":"market","behavior":"stationary","lines":["Welcome to my market stall! Look at the goods on my table.","Travelers always need provisions for the road."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"activity":"trade","kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Alda the Innkeeper","data":{"name":"Alda the Innkeeper","role":"innkeeper","x":25,"z":23.8,"color":9784643,"station":"inn","behavior":"stationary","lines":["Welcome to the Stag & Lantern! Take a seat by the tables and rest your feet.","Oakcross is the main town of the Heartlands. Everyone passes through our square sooner or later."],"attackType":"punch","level":5,"hp":45,"damage":4,"attackSpeed":2.4,"activity":"trade","kind":"npc","template":"villager","roam":0,"respawn":30,"attackable":false,"hostile":false}},{"id":"base:npc:Steward Elian","data":{"name":"Steward Elian","role":"steward","x":10,"z":-31.7,"color":4153722,"station":"hall","behavior":"stationary","lines":["Welcome to Oakcross Town Hall. Our town links the roads of the Heartlands.","The bank, chapel, forge, market and inn all serve the folk who call this place home."],"attackType":"pu